# ---- Batch 1 lessons: if/else, find the bug, speed race, secret messages ----
AGES.update({'cond': '7-10', 'bug': '8-12', 'race': '11-15', 'cipher': '9-13'})
ORDER[:] = ['bits', 'loop', 'vars', 'cond', 'bug', 'bfs', 'dfs', 'bs', 'sel', 'ins', 'bin', 'race', 'cipher', 'sq', 'topo', 'heap', 'dij', 'bf', 'prim', 'kruskal', 'qs', 'ms']
EN.update({
 'cond': ('Play "If you ...": call out rules such as "If your name has an A, stand up. Otherwise, sit down." Change the rule and play again, then add a second rule with "otherwise if".',
          [('The temperature is 6. Which branch runs: temp < 0, temp < 10 or else?', 'temp < 10, so "wear a hat". 6 is not smaller than 0, but it is smaller than 10.'), ('What does ELSE do?', 'It runs only when every question above it was false.'), ('Can two branches of the same if run in one go?', 'No. The first true branch is chosen and the others are skipped.')]),
 'bug': ('Give students a short recipe or set of instructions with one wrong step (for example, a robot walk that turns the wrong way). They follow it with a pencil, find the mistake and fix it.',
          [('What is a bug?', 'A mistake in a program.'), ('A program should give 6 but gives 5. What do you do first?', 'Run it line by line and write down the boxes after every line to find where it goes wrong.'), ('Why should you not change lines at random?', 'You may break something else. Find the broken line first, then fix it.')]),
 'race': ('Race with cards: n students hold a number. The Walker checks every number, the Waddler checks every pair, the Slider repeatedly halves the group. Count the steps out loud for 8 and 16 students.',
          [('A pile has 8 items. How many steps does the Walker need?', '8.'), ('A pile has 8 items. How many steps does the Waddler need?', '64, because 8 × 8 = 64.'), ('A pile has 16 items. How many times can the Slider halve it?', '4 times, because 2 × 2 × 2 × 2 = 16.')]),
 'cipher': ('Make two paper alphabet wheels, one inside the other. Turn the inner one by 3 and let pairs write short secret messages for each other, then decode them by turning the wheel back.',
          [('With a shift of 3, what does C become?', 'F.'), ('With a shift of 3, what does Y become?', 'B, because after Z the alphabet starts again at A.'), ('Why is this code not safe for real secrets?', 'There are only 25 shifts, so anyone can try them all.')]),
})
EL.update({
 'cond': ('Παίξτε «Αν …»: πείτε κανόνες όπως «Αν το όνομά σου έχει A, σήκω όρθιος. Αλλιώς κάθισε.» Αλλάξτε τον κανόνα και ξαναπαίξτε, μετά προσθέστε και δεύτερο κανόνα με «αλλιώς αν».',
          [('Η θερμοκρασία είναι 6. Ποιος κλάδος εκτελείται: temp < 0, temp < 10 ή αλλιώς;', 'Το temp < 10, άρα «φόρα σκούφο». Το 6 δεν είναι μικρότερο από το 0, αλλά είναι μικρότερο από το 10.'), ('Τι κάνει το ΑΛΛΙΩΣ;', 'Εκτελείται μόνο όταν όλες οι ερωτήσεις από πάνω ήταν ψευδείς.'), ('Μπορούν δύο κλάδοι του ίδιου «αν» να εκτελεστούν μαζί;', 'Όχι. Διαλέγεται ο πρώτος αληθής κλάδος και οι άλλοι προσπερνιούνται.')]),
 'bug': ('Δώστε στους μαθητές μια μικρή συνταγή ή σειρά οδηγιών με ένα λάθος βήμα (για παράδειγμα, ένα ρομπότ που στρίβει λάθος). Την ακολουθούν με μολύβι, βρίσκουν το λάθος και το διορθώνουν.',
          [('Τι είναι σφάλμα (bug);', 'Ένα λάθος σε ένα πρόγραμμα.'), ('Ένα πρόγραμμα έπρεπε να δώσει 6 αλλά δίνει 5. Τι κάνεις πρώτα;', 'Το τρέχεις γραμμή προς γραμμή και γράφεις τα κουτιά μετά από κάθε γραμμή, για να βρεις πού πάει στραβά.'), ('Γιατί δεν πρέπει να αλλάζεις γραμμές στην τύχη;', 'Μπορεί να χαλάσεις κάτι άλλο. Βρες πρώτα τη χαλασμένη γραμμή και μετά διόρθωσέ την.')]),
 'race': ('Αγώνας με κάρτες: n μαθητές κρατούν έναν αριθμό. Ο Περπατητής ελέγχει κάθε αριθμό, ο Αργοπόρος κάθε ζευγάρι, ο Γλιστρητής κόβει την ομάδα στη μέση ξανά και ξανά. Μετρήστε δυνατά τα βήματα για 8 και για 16 μαθητές.',
          [('Μια στοίβα έχει 8 αντικείμενα. Πόσα βήματα χρειάζεται ο Περπατητής;', '8.'), ('Μια στοίβα έχει 8 αντικείμενα. Πόσα βήματα χρειάζεται ο Αργοπόρος;', '64, γιατί 8 × 8 = 64.'), ('Μια στοίβα έχει 16 αντικείμενα. Πόσες φορές μπορεί να την κόψει στη μέση ο Γλιστρητής;', '4 φορές, γιατί 2 × 2 × 2 × 2 = 16.')]),
 'cipher': ('Φτιάξτε δύο χάρτινους τροχούς με το αλφάβητο, τον ένα μέσα στον άλλο. Γυρίστε τον εσωτερικό κατά 3 και αφήστε τα ζευγάρια να γράφουν μικρά μυστικά μηνύματα το ένα στο άλλο, και μετά να τα αποκωδικοποιούν γυρίζοντας τον τροχό πίσω.',
          [('Με μετατόπιση 3, σε τι γίνεται το C;', 'Σε F.'), ('Με μετατόπιση 3, σε τι γίνεται το Y;', 'Σε B, γιατί μετά το Z το αλφάβητο ξαναρχίζει από το A.'), ('Γιατί αυτός ο κώδικας δεν είναι ασφαλής για πραγματικά μυστικά;', 'Υπάρχουν μόνο 25 μετατοπίσεις, οπότε ο καθένας μπορεί να τις δοκιμάσει όλες.')]),
})

# ---- Batch 2 lessons ----
AGES.update({'rep': '9-13', 'net': '11-15', 'ai': '11-15', 'data': '9-13'})
ORDER[:] = ['bits', 'loop', 'vars', 'cond', 'bug', 'bfs', 'dfs', 'bs', 'sel', 'ins', 'bin', 'rep', 'race', 'cipher', 'sq', 'net', 'data', 'ai', 'topo', 'heap', 'dij', 'bf', 'prim', 'kruskal', 'qs', 'ms']
EN.update({
 'rep': ('Give every student the alphabet with numbers (A = 1 ... Z = 26). They write their name as numbers, swap with a partner and decode each other. Then draw a 5 x 5 grid, colour in a simple picture and write each row as 0s and 1s.',
         [('What number does the letter D get if A = 1?', '4.'), ('In a black and white picture, what do 1 and 0 mean?', '1 is a dark pixel and 0 is a light pixel.'), ('Write the row "dark, light, dark" as numbers.', '101.')]),
 'net': ('Write a sentence on a strip of paper and cut it into pieces of 3 letters. Number each piece, mix them up, pass them to a partner and let them rebuild the sentence. Remove one piece and see how the partner notices.',
         [('Why does every packet get a number?', 'So the receiver can put the packets back in the right order and see which one is missing.'), ('A message has 12 letters and each packet holds 4. How many packets?', '3.'), ('What happens when a packet gets lost?', 'The receiver asks the sender to send that packet again.')]),
 'data': ('Ask the class how many siblings, pets or books they have. Draw a bar chart on the board together, then find the biggest, the smallest, the total and the average.',
          [('What does a taller bar mean?', 'A bigger number.'), ('The numbers are 2, 4 and 6. What is the average?', '4, because 12 divided by 3 is 4.'), ('Can two different weeks have the same average?', 'Yes. That is why we also look at the chart.')]),
 'ai': ('Draw 6 example animals on the board as dots with two numbers each (size and weight), in two groups. Add a new animal and let students find the nearest example and guess its group. Then discuss: what if our examples were unfair?',
        [('What does the computer do with a new penguin?', 'It finds the nearest example and copies its group.'), ('Where do the computer\'s answers come from?', 'From the examples we gave it.'), ('Why can a computer guess wrong?', 'If the examples are unfair or missing, it copies their mistakes.')]),
})
EL.update({
 'rep': ('Δώστε σε κάθε μαθητή το αλφάβητο με αριθμούς (A = 1 ... Z = 26). Γράφουν το όνομά τους ως αριθμούς, το ανταλλάσσουν με έναν συμμαθητή και το αποκωδικοποιούν. Μετά ζωγραφίζουν ένα πλέγμα 5 x 5, χρωματίζουν μια απλή εικόνα και γράφουν κάθε γραμμή με 0 και 1.',
         [('Ποιον αριθμό παίρνει το γράμμα D αν A = 1;', '4.'), ('Σε μια ασπρόμαυρη εικόνα, τι σημαίνουν το 1 και το 0;', 'Το 1 είναι σκούρο εικονοστοιχείο και το 0 ανοιχτό.'), ('Γράψε τη γραμμή «σκούρο, ανοιχτό, σκούρο» ως αριθμούς.', '101.')]),
 'net': ('Γράψτε μια πρόταση σε μια λωρίδα χαρτί και κόψτε την σε κομμάτια των 3 γραμμάτων. Αριθμήστε κάθε κομμάτι, ανακατέψτε τα, δώστε τα σε έναν συμμαθητή και αφήστε τον να ξαναφτιάξει την πρόταση. Αφαιρέστε ένα κομμάτι και δείτε πώς το καταλαβαίνει.',
         [('Γιατί κάθε πακέτο παίρνει έναν αριθμό;', 'Για να βάλει ο παραλήπτης τα πακέτα στη σωστή σειρά και να δει ποιο λείπει.'), ('Ένα μήνυμα έχει 12 γράμματα και κάθε πακέτο χωράει 4. Πόσα πακέτα;', '3.'), ('Τι γίνεται όταν χαθεί ένα πακέτο;', 'Ο παραλήπτης ζητά από τον αποστολέα να στείλει ξανά αυτό το πακέτο.')]),
 'data': ('Ρωτήστε την τάξη πόσα αδέλφια, κατοικίδια ή βιβλία έχουν. Ζωγραφίστε μαζί ένα γράφημα με ράβδους στον πίνακα και βρείτε το μεγαλύτερο, το μικρότερο, το σύνολο και τον μέσο όρο.',
          [('Τι σημαίνει μια πιο ψηλή ράβδος;', 'Έναν μεγαλύτερο αριθμό.'), ('Οι αριθμοί είναι 2, 4 και 6. Ποιος είναι ο μέσος όρος;', '4, γιατί 12 διά 3 κάνει 4.'), ('Μπορούν δύο διαφορετικές εβδομάδες να έχουν τον ίδιο μέσο όρο;', 'Ναι. Γι’ αυτό κοιτάμε και το γράφημα.')]),
 'ai': ('Ζωγραφίστε στον πίνακα 6 ζώα-παραδείγματα ως τελείες με δύο αριθμούς το καθένα (μέγεθος και βάρος), σε δύο ομάδες. Προσθέστε ένα νέο ζώο και αφήστε τους μαθητές να βρουν το πιο κοντινό παράδειγμα και να μαντέψουν την ομάδα του. Συζητήστε: τι θα γινόταν αν τα παραδείγματά μας ήταν άδικα;',
        [('Τι κάνει ο υπολογιστής με έναν νέο πιγκουίνο;', 'Βρίσκει το πιο κοντινό παράδειγμα και αντιγράφει την ομάδα του.'), ('Από πού προέρχονται οι απαντήσεις του υπολογιστή;', 'Από τα παραδείγματα που του δώσαμε.'), ('Γιατί μπορεί ένας υπολογιστής να μαντέψει λάθος;', 'Αν τα παραδείγματα είναι άδικα ή λείπουν, αντιγράφει τα λάθη τους.')]),
})

