ORDER[:] = ['bits', 'hw', 'loop', 'vars', 'types', 'cond', 'robot', 'algo', 'bug', 'arr', 'func', 'logic', 'os', 'sheet', 'db', 'sec', 'cit', 'bfs', 'dfs', 'bs', 'sel', 'ins', 'bin',
            'rep', 'race', 'cipher', 'net', 'data', 'ai', 'rec', 'topo', 'sq', 'heap', 'dij', 'bf', 'prim', 'kruskal', 'qs', 'ms']
EN.update({
 'robot': ('Mark a 5 x 5 grid on the floor with tape and hide a paper fish. One student is the robot and may only follow the commands "forward", "turn right" and "turn left". The class writes the program on the board first, then the robot runs it exactly.',
           [('The penguin looks north and gets "turn right", then "forward". Which way does it move?', 'East, because turning right makes it look east.'), ('What does "repeat 3 times: forward" do?', 'It moves forward 3 squares. A loop saves writing the same command three times.'), ('The robot ends one square short of the fish. What do you do?', 'Run the program step by step, find the command that went wrong and fix only that one.')]),
 'algo': ('Write the steps for making a jam sandwich on cards, in a mixed-up order. Pairs put them in order and then draw the steps as a flowchart. Add a question diamond: "Is there jam left?"',
          [('What does an oval mean in a flowchart?', 'Start or End.'), ('What does a diamond mean?', 'A question with a yes arrow and a no arrow.'), ('Why do we draw an algorithm before programming it?', 'It shows the order and the choices clearly, so mistakes are easy to see.')]),
 'logic': ('Two students hold hands to show AND: the lamp is on only when both are holding hands up. Then try OR (at least one up) and NOT (the opposite). Fill in the truth table together.',
           [('AND: A is 1 and B is 0. What is the lamp?', '0 (off). AND needs both to be 1.'), ('OR: A is 1 and B is 0. What is the lamp?', '1 (on). OR needs at least one 1.'), ('NOT: the input is 0. What is the lamp?', '1 (on). NOT flips the input.')]),
 'types': ('Put cards with 7, "7", hello, 3.5, true and "cat" on the board. Students sort them into three bins: numbers, text and true/false. Discuss why "7" in quotes is text.',
           [('What is 3 + 4 for numbers, and "3" + "4" for text?', '7 for numbers. For text the pieces are stuck together and give "34".'), ('Which type is true?', 'True or false (a boolean).'), ('Why does the computer need types?', 'The type tells it what it may do with a value, for example add numbers or join text.')]),
 'arr': ('Line up 5 students with numbers 0 to 4 on their shirts (stickers). Call out "read box 3" or "write 9 into box 1". Then make a 3 x 3 grid of students for a table.',
         [('An array has 6 boxes. What is the index of the last one?', '5, because counting starts at 0.'), ('a = [4, 8, 2]. What is a[1]?', '8.'), ('What does table[2][0] mean?', 'Row 2, column 0.')]),
 'func': ('Be a "function machine": the student behind a desk follows a rule (for example "double it"). The class calls in numbers and the machine answers. Then change the rule and play again.',
          [('double(x) = x * 2. What is double(7)?', '14.'), ('area(w, h) = w * h. What is area(3, 5)?', '15.'), ('Why write a function instead of repeating the steps?', 'You write the recipe once and use it many times.')]),
 'rec': ('Use nesting boxes or cups of different sizes. Open them one by one, and then say what happens when you reach the smallest one. Then act out fact(4): each student waits for the answer from the next student.',
         [('What is the base case of fact(n)?', 'fact(1) = 1. It stops the calling.'), ('What is fact(4)?', '24, because 4 × 3 × 2 × 1 = 24.'), ('What happens without a base case?', 'The calls never stop and the program crashes.')]),
 'hw': ('Make five signs: Input, CPU, Memory, Storage and Output. Walk through "type a letter" and "save a drawing" together, and let students stand at the sign where each thing happens.',
        [('Which part is the keyboard?', 'Input.'), ('Which part forgets everything when the power goes off?', 'Memory (RAM).'), ('Where does a saved picture stay for tomorrow?', 'In storage.')]),
 'os': ('Draw a folder tree of a school bag on the board (Bag, Books, Maths, Art...). Students write the path to each item. Then let them design a tidy folder tree for their own computer or tablet.',
        [('What is the path of homework.txt in School/Maths?', 'School/Maths/homework.txt, the folder names joined with /.'), ('Can two files share a name?', 'Yes, if they are in different folders, because their paths differ.'), ('What is the top folder called?', 'The root.')]),
 'sheet': ('Use a paper grid. Students write their own numbers (for example the pocket money they saved each week) in column A, then write the formula for the total in a cell and recalculate by hand when one number changes.',
           [('Which cell is in column C, row 4?', 'C4.'), ('A1 is 3 and B1 is 5. What does =A1+B1 show?', '8.'), ('A1:A3 holds 2, 4 and 6. What does =SUM(A1:A3) show?', '12.')]),
 'db': ('Collect facts about the class on cards (name, age, favourite animal). Treat them as a table. Filter ("favourite animal is penguin"), count and sort by age with real cards.',
        [('What is one row of a table called?', 'A record.'), ('What does a filter do?', 'It keeps only the rows that match a rule.'), ('Sorting by age, smallest first: who comes first?', 'The youngest.')]),
 'sec': ('Students invent a long made-up password sentence on paper, then check it against the five tests. Then give pairs a pretend message and let them circle the clues. Remind everyone never to use a real password in class.',
         [('Name two things that make a password strong.', 'Long, and a mix of capital letters, small letters, numbers and symbols.'), ('A message says "act in 5 minutes and send your password". What do you do?', 'Do not click or reply, and show a grown-up.'), ('Is it fine to share a password with a best friend?', 'No. A password stays secret.')]),
 'cit': ('Act out short scenes (a stranger asks where you live, a friend wants to copy text, a rude comment). The class decides together what a good digital citizen does and why.',
         [('Name two kinds of personal information to keep private.', 'For example: address, school, phone number, passwords.'), ('You want to use a photo from the internet. What do you check and do?', 'Check the licence and write who made it.'), ('Name two clues that a website can be trusted.', 'It names the author and the date, and says where the facts come from.')]),
})
EL.update({
 'robot': ('Σημειώστε με ταινία ένα πλέγμα 5 x 5 στο πάτωμα και κρύψτε ένα χάρτινο ψάρι. Ένας μαθητής είναι το ρομπότ και μπορεί να εκτελεί μόνο τις εντολές «μπροστά», «στρίψε δεξιά» και «στρίψε αριστερά». Η τάξη γράφει πρώτα το πρόγραμμα στον πίνακα και μετά το ρομπότ το εκτελεί ακριβώς.',
           [('Ο πιγκουίνος κοιτάζει βόρεια και παίρνει «στρίψε δεξιά» και μετά «μπροστά». Προς τα πού πηγαίνει;', 'Ανατολικά, γιατί αφού στρίψει δεξιά κοιτάζει ανατολικά.'), ('Τι κάνει το «επανάλαβε 3 φορές: μπροστά»;', 'Προχωρά 3 τετράγωνα μπροστά. Ένας βρόχος γλιτώνει να γράφεις την ίδια εντολή τρεις φορές.'), ('Το ρομπότ σταματά ένα τετράγωνο πριν από το ψάρι. Τι κάνεις;', 'Τρέχεις το πρόγραμμα βήμα βήμα, βρίσκεις την εντολή που πήγε στραβά και διορθώνεις μόνο εκείνη.')]),
 'algo': ('Γράψτε τα βήματα για να φτιάξετε ένα σάντουιτς με μαρμελάδα σε κάρτες, με ανακατεμένη σειρά. Τα ζευγάρια τα βάζουν σε σειρά και μετά σχεδιάζουν τα βήματα ως διάγραμμα ροής. Προσθέστε ένα ρόμβο ερώτησης: «Έμεινε μαρμελάδα;»',
          [('Τι σημαίνει το οβάλ σε ένα διάγραμμα ροής;', 'Αρχή ή Τέλος.'), ('Τι σημαίνει ο ρόμβος;', 'Μια ερώτηση με βέλος ναι και βέλος όχι.'), ('Γιατί σχεδιάζουμε έναν αλγόριθμο πριν τον προγραμματίσουμε;', 'Δείχνει καθαρά τη σειρά και τις επιλογές, ώστε τα λάθη να φαίνονται εύκολα.')]),
 'logic': ('Δύο μαθητές πιάνονται από τα χέρια για να δείξουν το AND: η λάμπα ανάβει μόνο όταν και οι δύο σηκώνουν το χέρι. Μετά δοκιμάστε το OR (τουλάχιστον ένας) και το NOT (το αντίθετο). Συμπληρώστε μαζί τον πίνακα αλήθειας.',
           [('AND: το A είναι 1 και το B είναι 0. Τι δείχνει η λάμπα;', '0 (σβηστή). Το AND θέλει και τα δύο να είναι 1.'), ('OR: το A είναι 1 και το B είναι 0. Τι δείχνει η λάμπα;', '1 (αναμμένη). Το OR θέλει τουλάχιστον ένα 1.'), ('NOT: η είσοδος είναι 0. Τι δείχνει η λάμπα;', '1 (αναμμένη). Το NOT αντιστρέφει την είσοδο.')]),
 'types': ('Βάλτε στον πίνακα κάρτες με 7, "7", hello, 3.5, true και "cat". Οι μαθητές τις ταξινομούν σε τρία καλάθια: αριθμοί, κείμενο και αληθές/ψευδές. Συζητήστε γιατί το "7" σε εισαγωγικά είναι κείμενο.',
           [('Τι κάνει το 3 + 4 για αριθμούς και το "3" + "4" για κείμενο;', 'Για αριθμούς 7. Για κείμενο τα κομμάτια κολλάνε μαζί και βγαίνει "34".'), ('Ποιου τύπου είναι το true;', 'Αληθές ή ψευδές (λογική τιμή).'), ('Γιατί χρειάζεται ο υπολογιστής τύπους;', 'Ο τύπος του λέει τι επιτρέπεται να κάνει με μια τιμή, για παράδειγμα να προσθέσει αριθμούς ή να ενώσει κείμενο.')]),
 'arr': ('Βάλτε στη σειρά 5 μαθητές με αριθμούς 0 έως 4 στα μπλουζάκια τους (αυτοκόλλητα). Φωνάξτε «διάβασε το κουτί 3» ή «γράψε 9 στο κουτί 1». Μετά φτιάξτε ένα πλέγμα 3 x 3 από μαθητές για έναν πίνακα.',
         [('Ένας πίνακας (array) έχει 6 κουτιά. Ποιος είναι ο δείκτης του τελευταίου;', '5, γιατί η μέτρηση ξεκινά από το 0.'), ('a = [4, 8, 2]. Πόσο είναι το a[1];', '8.'), ('Τι σημαίνει το table[2][0];', 'Γραμμή 2, στήλη 0.')]),
 'func': ('Γίνετε «μηχανή συνάρτησης»: ο μαθητής πίσω από ένα θρανίο ακολουθεί έναν κανόνα (για παράδειγμα «διπλασίασέ το»). Η τάξη φωνάζει αριθμούς και η μηχανή απαντά. Μετά αλλάξτε τον κανόνα και ξαναπαίξτε.',
          [('double(x) = x * 2. Πόσο είναι το double(7);', '14.'), ('area(w, h) = w * h. Πόσο είναι το area(3, 5);', '15.'), ('Γιατί γράφουμε συνάρτηση αντί να επαναλαμβάνουμε τα βήματα;', 'Γράφεις τη συνταγή μία φορά και τη χρησιμοποιείς πολλές φορές.')]),
 'rec': ('Χρησιμοποιήστε κουτιά ή κύπελλα διαφορετικού μεγέθους που χωράνε το ένα μέσα στο άλλο. Ανοίξτε τα ένα-ένα και πείτε τι γίνεται όταν φτάσετε στο μικρότερο. Μετά παίξτε το fact(4): κάθε μαθητής περιμένει την απάντηση του επόμενου.',
         [('Ποια είναι η βασική περίπτωση του fact(n);', 'fact(1) = 1. Σταματά τις κλήσεις.'), ('Πόσο είναι το fact(4);', '24, γιατί 4 × 3 × 2 × 1 = 24.'), ('Τι γίνεται χωρίς βασική περίπτωση;', 'Οι κλήσεις δεν σταματούν ποτέ και το πρόγραμμα καταρρέει.')]),
 'hw': ('Φτιάξτε πέντε πινακίδες: Είσοδος, CPU, Μνήμη, Αποθήκευση και Έξοδος. Περάστε μαζί το «γράφω ένα γράμμα» και το «αποθηκεύω ένα σχέδιο» και αφήστε τους μαθητές να στέκονται στην πινακίδα όπου γίνεται κάθε πράγμα.',
        [('Ποιο μέρος είναι το πληκτρολόγιο;', 'Η είσοδος.'), ('Ποιο μέρος ξεχνά τα πάντα όταν σβήσει το ρεύμα;', 'Η μνήμη (RAM).'), ('Πού μένει μια αποθηκευμένη εικόνα για αύριο;', 'Στην αποθήκευση.')]),
 'os': ('Σχεδιάστε στον πίνακα το δέντρο φακέλων μιας σχολικής τσάντας (Τσάντα, Βιβλία, Μαθηματικά, Καλλιτεχνικά...). Οι μαθητές γράφουν τη διαδρομή για κάθε αντικείμενο. Μετά αφήστε τους να σχεδιάσουν ένα τακτικό δέντρο φακέλων για τον δικό τους υπολογιστή ή τάμπλετ.',
        [('Ποια είναι η διαδρομή του homework.txt στο School/Maths;', 'School/Maths/homework.txt, τα ονόματα των φακέλων ενωμένα με /.'), ('Μπορούν δύο αρχεία να έχουν το ίδιο όνομα;', 'Ναι, αν είναι σε διαφορετικούς φακέλους, γιατί οι διαδρομές τους διαφέρουν.'), ('Πώς λέγεται ο πάνω φάκελος;', 'Ρίζα.')]),
 'sheet': ('Χρησιμοποιήστε ένα χάρτινο πλέγμα. Οι μαθητές γράφουν δικούς τους αριθμούς (για παράδειγμα το χαρτζιλίκι που έβαλαν στην άκρη κάθε εβδομάδα) στη στήλη A, μετά γράφουν τον τύπο για το σύνολο σε ένα κελί και ξαναϋπολογίζουν με το χέρι όταν αλλάζει ένας αριθμός.',
           [('Ποιο κελί είναι στη στήλη C, γραμμή 4;', 'Το C4.'), ('Το A1 είναι 3 και το B1 είναι 5. Τι δείχνει το =A1+B1;', '8.'), ('Το A1:A3 έχει 2, 4 και 6. Τι δείχνει το =SUM(A1:A3);', '12.')]),
 'db': ('Μαζέψτε στοιχεία για την τάξη σε κάρτες (όνομα, ηλικία, αγαπημένο ζώο). Δείτε τα ως πίνακα. Φιλτράρετε («αγαπημένο ζώο ο πιγκουίνος»), μετρήστε και ταξινομήστε κατά ηλικία με πραγματικές κάρτες.',
        [('Πώς λέγεται μία γραμμή ενός πίνακα;', 'Εγγραφή.'), ('Τι κάνει ένα φίλτρο;', 'Κρατά μόνο τις γραμμές που ταιριάζουν σε έναν κανόνα.'), ('Ταξινόμηση κατά ηλικία, πρώτο το μικρότερο: ποιος έρχεται πρώτος;', 'Ο νεότερος.')]),
 'sec': ('Οι μαθητές επινοούν στο χαρτί μια μακριά φανταστική πρόταση-κωδικό και την ελέγχουν με τα πέντε τεστ. Μετά δώστε στα ζευγάρια ένα προσποιητό μήνυμα και αφήστε τα να κυκλώσουν τις ενδείξεις. Υπενθυμίστε σε όλους να μην χρησιμοποιούν ποτέ πραγματικό κωδικό στην τάξη.',
         [('Πες δύο πράγματα που κάνουν έναν κωδικό δυνατό.', 'Είναι μακρύς και ανακατεύει κεφαλαία, μικρά γράμματα, αριθμούς και σύμβολα.'), ('Ένα μήνυμα λέει «κάνε κάτι σε 5 λεπτά και στείλε τον κωδικό σου». Τι κάνεις;', 'Δεν πατάς ούτε απαντάς και το δείχνεις σε έναν μεγαλύτερο.'), ('Είναι εντάξει να μοιραστείς τον κωδικό σου με τον καλύτερό σου φίλο;', 'Όχι. Ο κωδικός μένει μυστικός.')]),
 'cit': ('Παίξτε μικρές σκηνές (ένας άγνωστος ρωτά πού μένεις, ένας φίλος θέλει να αντιγράψει ένα κείμενο, ένα αγενές σχόλιο). Η τάξη αποφασίζει μαζί τι κάνει ένας καλός ψηφιακός πολίτης και γιατί.',
         [('Πες δύο είδη προσωπικών στοιχείων που μένουν ιδιωτικά.', 'Για παράδειγμα: διεύθυνση, σχολείο, τηλέφωνο, κωδικοί.'), ('Θέλεις να χρησιμοποιήσεις μια φωτογραφία από το διαδίκτυο. Τι ελέγχεις και τι κάνεις;', 'Ελέγχεις την άδεια χρήσης και γράφεις ποιος την έφτιαξε.'), ('Πες δύο ενδείξεις ότι ένας ιστότοπος είναι αξιόπιστος.', 'Αναφέρει συγγραφέα και ημερομηνία και λέει από πού προέρχονται τα στοιχεία.')]),
})
